import sys

def solve():
    try:
        line = sys.stdin.read().strip()
        if not line:
            return
        n = int(line)
    except ValueError:
        return

    results = []

    def backtrack(current, ones, zeros):
        if len(current) == n:
            results.append(current)
            return

        # Try adding '1'
        if ones + 1 <= n:
            backtrack(current + '1', ones + 1, zeros)

        # Try adding '0' only if condition holds (ones > zeros)
        if zeros + 1 <= ones:
            backtrack(current + '0', ones, zeros + 1)

    backtrack("", 0, 0)

    # The generation order (trying '1' then '0') naturally produces decreasing order
    # because we build from left to right and prioritize higher bits.
    # However, let's ensure it matches the requirement explicitly if needed.
    # The recursive structure:
    # Level 1: "1..." comes before "0..." (but "0..." is never added at start since ones=0, zeros=0 fails zeros+1<=ones)
    # So all start with '1'.
    # At any point, appending '1' is done before appending '0'.
    # Since we append to the list in DFS order, and '1' > '0', the resulting list is already in decreasing lexicographical order.

    for s in results:
        print(s)

if __name__ == "__main__":
    solve()
